examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
        Text({{title}}).monarchTextStyle(.bodyStrong)
        Text({{dateLabel}}).monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
    }
    .accessibilityElement(children: .combine)
    .accessibilityAddTraits(.isHeader)
    Text({{schedule}}).monarchTextStyle(.caption).textCase(.uppercase).foregroundStyle(theme.colors.textMuted)
    MonarchAgendaList(
        [
            MonarchAgendaEvent({{events.0.title}}, id: {{events.0.id}}, start: {{events.0.start|date}}, end: {{events.0.end|date}}, detail: {{events.0.detail}}, color: theme.colors.accentStrong),
            MonarchAgendaEvent({{events.1.title}}, id: {{events.1.id}}, start: {{events.1.start|date}}, end: {{events.1.end|date}}, color: theme.colors.accentStrong),
        ],
        from: {{today|date}},
        days: 1,
        today: {{today|date}},
        calendar: {
            var calendar = Calendar(identifier: .gregorian)
            calendar.timeZone = TimeZone(identifier: {{timeZone}}) ?? .gmt
            return calendar
        }()
    )
    .environment(\.locale, Locale(identifier: {{locale}}))
    .frame(height: 230)
    Text({{dueToday}}).monarchTextStyle(.caption).textCase(.uppercase).foregroundStyle(theme.colors.textMuted)
    HStack {
        Toggle({{tasks.0.title}}, isOn: isDone({{tasks.0.id}}))
            .toggleStyle(.monarchCheckbox)
        Spacer(minLength: 0)
        if {{tasks.0.overdue}} {
            MonarchBadge({{overdueLabel}}, tone: .danger)
        }
        Text({{tasks.0.due}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.dangerStrong)
    }
    VStack(alignment: .leading) {
        Toggle({{tasks.1.title}}, isOn: isDone({{tasks.1.id}}))
            .toggleStyle(.monarchCheckbox)
        Text({{tasks.1.detail}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            .padding(.leading, theme.spacing.space8)
    }
    HStack {
        Toggle({{tasks.2.title}}, isOn: isDone({{tasks.2.id}}))
            .toggleStyle(.monarchCheckbox)
        Spacer(minLength: 0)
        MonarchBadge({{tasks.2.badge.text}}, tone: {{tasks.2.badge.tone|tone}})
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var done: Set<String> = []

private func isDone(_ id: String) -> Binding<Bool> {
    Binding(
        get: { done.contains(id) },
        set: { on in
            if on { done.insert(id) } else { done.remove(id) }
        }
    )
}

