    MonarchAgendaList(
        [
            MonarchAgendaEvent("Weekly review", id: "e1", start: Date(timeIntervalSince1970: 1_794_043_800), end: Date(timeIntervalSince1970: 1_794_045_600), detail: "Room 2", color: theme.colors.accentStrong),
            MonarchAgendaEvent("Interview: product designer", id: "e2", start: Date(timeIntervalSince1970: 1_794_056_400), end: Date(timeIntervalSince1970: 1_794_060_000), color: theme.colors.accentStrong),
        ],
        from: Date(timeIntervalSince1970: 1_794_009_600),
        days: 1,
        today: Date(timeIntervalSince1970: 1_794_009_600),
        calendar: {
            var calendar = Calendar(identifier: .gregorian)
            calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
            return calendar
        }()
    )
    .environment(\.locale, Locale(identifier: "en-GB"))
    .frame(height: 230)
    Text("Due today").monarchTextStyle(.caption).textCase(.uppercase).foregroundStyle(theme.colors.textMuted)
    HStack {
        Toggle("Approve 3 time-off requests", isOn: isDone("t2"))
            .toggleStyle(.monarchCheckbox)
        Spacer(minLength: 0)
        if true {
            MonarchBadge("Overdue", tone: .danger)
        }
